from __future__ import annotations

from typing import Annotated, List, Optional

from pydantic import BaseModel, ConfigDict, Field


class Frontmatter(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    title: Annotated[str, Field(description="Article title.")]
    date: Annotated[
        str,
        Field(
            description="Publication date in YYYY-MM-DD.",
            pattern="^\\d{4}-\\d{2}-\\d{2}$",
        ),
    ]
    description: Annotated[
        str, Field(description="Short article description / excerpt.")
    ]
    tags: Annotated[List[str], Field(description="Theme tags.")]
    image: Annotated[
        Optional[str],
        Field(
            description="Hero image filename; empty at generation time, filled by the Imagen step."
        ),
    ] = ""
    kind: Annotated[
        Optional[str], Field(description="Content kind (veille | blog).")
    ] = "veille"


class Article(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    date: Annotated[
        str,
        Field(
            description="Publication date in YYYY-MM-DD (Europe/Paris). Firestore document key and idempotency key.",
            pattern="^\\d{4}-\\d{2}-\\d{2}$",
        ),
    ]
    slug: Annotated[str, Field(description="URL slug derived from the article title.")]
    theme: Annotated[
        str,
        Field(
            description="The article's tech-watch theme; rendered as a TagPill in the PWA."
        ),
    ]
    frontmatter: Frontmatter
    body: Annotated[
        str,
        Field(
            description="Article body (Markdown), rendered with the prose-veilleur tokens."
        ),
    ]
    linkedin: Annotated[
        str,
        Field(
            description="Ready-to-post LinkedIn text (≤3000 chars). Consumed by the PWA share sheet (F-010)."
        ),
    ]
    image: Annotated[
        str,
        Field(
            description='Hero image filename, e.g. "2026-06-01.webp" (mirrors frontmatter.image). Resolved by the PWA against the public Astro images base URL.'
        ),
    ]
    commit_sha: Annotated[
        Optional[str],
        Field(
            description="GitHub commit SHA set by the `publish` step once the article lands on the Astro site; null before the commit."
        ),
    ] = None
    published: Annotated[
        Optional[bool],
        Field(
            description="False = recoverable pre-commit persist; true = live on the public site."
        ),
    ] = False
